package com.bank.balance;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class BalanceDemo {
    private static final Logger log = Logger.getLogger("Balance");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Txn> txns = List.of(
            new Txn("SAV2001", new BigDecimal("1000.00")),
            new Txn("CUR3001", new BigDecimal("250.00")),
            new Txn("SAV2001", new BigDecimal("500.00")),   // same account again
            new Txn("SAV2001", new BigDecimal("-200.00")));  // debit
        BalanceService service = new BalanceService();

        Map<String, BigDecimal> balances = service.balancesByAccount(txns);
        balances.forEach((acct, bal) -> log.info(() -> acct + " net balance = " + bal));
    }
}

// ─── Would be in model/Txn.java ───
record Txn(String accountId, BigDecimal amount) {}

// ─── Would be in service/BalanceService.java ───
class BalanceService {
    // toMap with merge function: collisions on accountId are summed
    Map<String, BigDecimal> balancesByAccount(List<Txn> txns) {
        return txns.stream().collect(
            java.util.stream.Collectors.toMap(
                Txn::accountId,            // key
                Txn::amount,               // value
                BigDecimal::add,           // merge: existing + new on collision
                java.util.LinkedHashMap::new)); // preserve first-seen order
    }
}
